async function loadSkills(target){const box=target||$('#config-skills');if(!box)return;try{const r=await api('/api/genesis/skills');renderSkills(r.skills||[],box);}catch(e){box.innerHTML='<p class="meta">'+esc(e.message)+'</p>';}}
