// ---- activity ----------------------------------------------------------------------------------
const ACTIVITY_WORDS={card:'Card created',stage:'Card moved',work:'Genesis started working',turn:'Turn started','turn-completed':'Turn finished','turn-failed':'Turn failed',plan:'Plan written',launch:'Run launched',waiting:'Plan waiting',question:'Question asked',answer:'Question answered',autonomy:'Autonomy changed',debrief:'Verdict asked for',declined:'Plan declined',skill:'Skill written','skill-removed':'Skill removed','plugin-error':'A plugin failed'};
let activityKind='',activityText='',genesisActivityTimer=null;
function activityLine(e){const card=genesisData?.cards.find(c=>c.id===e.card);const who=e.by?esc(String(e.by).replace('human:','').replace('genesis:','Genesis, ')):'';
 const detail=e.kind==='stage'?esc(stageWord(e.before)+' to '+stageWord(e.after)):e.kind==='declined'?esc(e.reason||''):e.kind==='card'?esc(e.title||''):e.kind==='launch'?'run '+esc(String(e.job||'').slice(0,12))+(e.maximum_usd?' · ceiling $'+esc(e.maximum_usd):''):e.kind==='plan'?esc((e.lines||[]).slice(0,2).join('; ')):e.kind==='waiting'?esc(e.reason||''):e.kind==='question'?esc(e.question||''):e.kind==='answer'?esc(e.answer||''):e.kind==='autonomy'?esc(e.setting+': '+e.before+' to '+e.after):e.kind==='turn-completed'?'cost $'+esc(String(e.cost_usd??0)):e.kind==='turn-failed'?esc(e.message||''):e.kind==='turn'?esc(e.model||'')+(e.purpose?' · '+esc(e.purpose):''):e.kind==='plugin-error'?esc(e.error||''):'';
 return '<tr><td class="meta">'+esc((e.at||'').slice(0,16).replace('T',' '))+'</td><td>'+esc(ACTIVITY_WORDS[e.kind]||e.kind)+(who?' <span class="meta">'+who+'</span>':'')+'</td><td>'+(e.card?'<button class="text-button" data-activity-card="'+esc(e.card)+'">'+esc(card?card.title.slice(0,60):e.card.slice(0,12))+'</button>':'')+'</td><td>'+detail+'</td></tr>';}
async function loadActivity(){const box=$('#genesis-activity');if(!box)return;box.innerHTML='<p class="node-help">Loading</p>';try{if(!genesisData)genesisData=await api('/api/genesis');const r=await api('/api/genesis/activity?limit=400');const all=r.entries||[];const kinds=[...new Set(all.map(e=>e.kind))];
 const entries=all.filter(e=>(!activityKind||e.kind===activityKind)&&(!activityText||JSON.stringify(e).toLowerCase().includes(activityText)));const cost=all.filter(e=>e.kind==='turn-completed').reduce((n,e)=>n+Number(e.cost_usd||0),0);
 box.innerHTML='<div class="activity-head"><label class="history-query"><span class="sr-only">Search the record</span><input id="activity-q" type="search" placeholder="Search the record" value="'+esc(activityText)+'"></label><label class="history-sort">Kind<select id="activity-kind"><option value="">Every kind</option>'+kinds.map(k=>option(k,ACTIVITY_WORDS[k]||k,k===activityKind)).join('')+'</select></label><span class="meta">'+entries.length+' of '+all.length+' entries · turns cost '+esc(money(cost))+'</span></div>'+(entries.length?'<div class="table-scroll"><table class="table activity-table"><thead><tr><th>When</th><th>What</th><th>Card</th><th>Detail</th></tr></thead><tbody>'+entries.map(activityLine).join('')+'</tbody></table></div>':'<div class="empty-state"><p>'+(all.length?'Nothing matches.':'Nothing recorded yet. The record starts with the first card, turn or launch.')+'</p></div>');
 $('#activity-q').oninput=e=>{activityText=e.target.value.trim().toLowerCase();clearTimeout(genesisActivityTimer);genesisActivityTimer=setTimeout(loadActivity,250);};$('#activity-kind').onchange=e=>{activityKind=e.target.value;loadActivity();};
 $$('[data-activity-card]').forEach(b=>b.onclick=()=>showResearchCard(b.dataset.activityCard));}catch(e){box.innerHTML='<div class="empty-state"><p>'+esc(e.message)+'</p></div>';}}

