// ---- the weekly digest: a public-safe page in the report style (design section 11) ----------
function isoWeek(d){const date=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const day=date.getUTCDay()||7;date.setUTCDate(date.getUTCDate()+4-day);const start=new Date(Date.UTC(date.getUTCFullYear(),0,1));return date.getUTCFullYear()+'-W'+String(Math.ceil(((date-start)/86400000+1)/7)).padStart(2,'0');}
async function loadDigest(){const box=$('#genesis-digest');if(!box)return;const input=$('#digest-week');if(!input.value)input.value=isoWeek(new Date());const week=input.value;box.innerHTML='<p class="meta">Reading the week…</p>';
 try{const d=await api('/api/genesis/digest?week='+encodeURIComponent(week));
  const list=(items,render,empty)=>items&&items.length?'<ul class="digest-list">'+items.map(render).join('')+'</ul>':'<p class="report-note">'+esc(empty)+'</p>';
  const day=s=>{const x=new Date(s+'T12:00:00Z');return isNaN(x)?s:x.toLocaleDateString('en-GB',{day:'numeric',month:'long',timeZone:'UTC'});};const last=new Date(d.to+'T12:00:00Z');last.setUTCDate(last.getUTCDate()-1);
  box.innerHTML='<header class="report-head"><h1>Genesis, week '+esc(d.week.slice(6).replace(/^0/,''))+' of '+esc(d.week.slice(0,4))+'</h1><p class="meta">'+esc(day(d.from))+' to '+esc(day(last.toISOString().slice(0,10)))+'.</p></header>'
  +'<section class="report-section"><h2>What ran</h2>'+list(d.ran,j=>'<li><a href="#report/'+encodeURIComponent(j.id)+'">'+esc(j.title)+'</a> <span class="meta">'+esc({completed:'finished',failed:'failed',running:'running',stopped:'stopped'}[j.status]||j.status||'')+'</span></li>','No run finished this week.')+'</section>'
  +'<section class="report-section"><h2>What was learned</h2>'+list(d.done,c=>'<li><button type="button" class="text-button" data-card="'+esc(c.id)+'">'+esc(c.title)+'</button></li>','No card reached Done this week.')+'</section>'
  +'<section class="report-section"><h2>Hypotheses settled</h2><h3>Supported</h3>'+list(d.supported,h=>'<li><button type="button" class="text-button" data-card="'+esc(h.id)+'">'+esc(h.title)+'</button>'+(h.reason?' <span class="meta">'+esc(h.reason)+'</span>':'')+'</li>','None supported yet.')+'<h3>Refuted</h3>'+list(d.refuted,h=>'<li><button type="button" class="text-button" data-card="'+esc(h.id)+'">'+esc(h.title)+'</button>'+(h.reason?' <span class="meta">'+esc(h.reason)+'</span>':'')+'</li>','None refuted yet.')+'</section>'
  +'<section class="report-section"><h2>Standings</h2><p>Standings are read from the round reports, one table per task set: <a href="#reports">Reports</a>.</p></section>'
  +'<section class="report-section"><h2>Calibration</h2><p>'+esc(d.track||'No calibration line yet.')+'</p></section>';
  $$('#genesis-digest [data-card]').forEach(b=>b.onclick=()=>showResearchCard(b.dataset.card));
 }catch(e){box.innerHTML='<p class="report-note">'+esc(e.message)+'</p>';}}
$('#digest-week')?.addEventListener('change',loadDigest);

// ---- the panes: fold to a strip, drag the edges; remembered per browser, written through CSSOM (no inline style) ----
(function(){const shell=$('.genesis-shell');if(!shell)return;const KEY='ailabs-genesis-panes',LIMITS={rail:[160,360],track:[260,640]};
 let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){saved={};}
 const sheet=new CSSStyleSheet();document.adoptedStyleSheets=[...document.adoptedStyleSheets,sheet];
 const apply=()=>{shell.classList.toggle('rail-folded',!!saved.railFolded);shell.classList.toggle('track-folded',!!saved.trackFolded);
  $('#rail-fold').setAttribute('aria-expanded',String(!saved.railFolded));$('#track-fold').setAttribute('aria-expanded',String(!saved.trackFolded));
  sheet.replaceSync('.genesis-shell{'+(saved.rail?'--genesis-rail:'+saved.rail+'px;':'')+(saved.track?'--genesis-track:'+saved.track+'px;':'')+'}');
  localStorage.setItem(KEY,JSON.stringify(saved));};
 $('#rail-fold').onclick=()=>{saved.railFolded=!saved.railFolded;apply();};$('#track-fold').onclick=()=>{saved.trackFolded=!saved.trackFolded;apply();};
 $$('.pane-handle').forEach(handle=>{handle.onpointerdown=e=>{const key=handle.dataset.handle,pane=key==='rail'?$('.genesis-rail'):$('.genesis-tracking'),base=pane.getBoundingClientRect().width,x0=e.clientX,[min,max]=LIMITS[key];
  handle.classList.add('dragging');handle.setPointerCapture(e.pointerId);
  handle.onpointermove=ev=>{const delta=key==='rail'?ev.clientX-x0:x0-ev.clientX;saved[key]=Math.round(Math.min(max,Math.max(min,base+delta)));apply();};
  handle.onpointerup=handle.onpointercancel=()=>{handle.classList.remove('dragging');handle.onpointermove=null;};};});
 apply();})();
